#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        assert_eq!(count_islands(&["##..#", "#...#", "..#..", "....#"]), 4);
    }

    #[test]
    fn empty() {
        assert_eq!(count_islands(&[]), 0);
        assert_eq!(count_islands(&[""]), 0);
    }

    #[test]
    fn all_water() {
        assert_eq!(count_islands(&["...", "..."]), 0);
    }

    #[test]
    fn diagonal_not_connected() {
        assert_eq!(count_islands(&["#.#", ".#.", "#.#"]), 5);
    }

    #[test]
    fn snake_and_large() {
        assert_eq!(count_islands(&["###", "..#", "###", "#..", "###"]), 1);
        let row = "#".repeat(300);
        let big: Vec<&str> = (0..300).map(|_| row.as_str()).collect();
        assert_eq!(count_islands(&big), 1);
    }
}
